#!/usr/bin/env node
/**
 * sync.mjs - fan site.config.js out to the surfaces that cannot import it.
 *
 * The docs identity that cannot be imported JS - Jekyll's docs/_config.yml and
 * freestruct's docs/freestruct.config.yml - is GENERATED here from the one
 * identity file. A generated file is never hand-edited; `--check` fails when
 * one has drifted, so the drift is caught at its source.
 *
 *   node scripts/sync.mjs           write every derived file
 *   node scripts/sync.mjs --check   refuse if any has drifted
 *
 * Zero dependencies on purpose (the family value): the YAML is hand-rendered
 * with a conservative quoter, and the Jekyll build is the real parse gate. A
 * deterministic writer: same config, same bytes, no wall clock.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')

// A YAML scalar is unsafe unquoted when it contains a colon+space (the value
// would read as a nested mapping), a leading indicator, a trailing space, or a
// control char. Quote whenever in doubt: JSON.stringify gives the right
// escapes and a quoted string is always valid.
const yamlStr = (v) => {
  const str = String(v)
  const unsafe =
    /:\s/.test(str) ||
    /^[\s\-?:,[\]{}#&*!|>'"%@`]/.test(str) ||
    /\s$/.test(str) ||
    str === '' ||
    /[\n\r\t]/.test(str)
  return unsafe ? JSON.stringify(str) : str
}

const site = (await import(pathToFileURL(join(ROOT, 'site.config.js')).href)).default

const BANNER = `# GENERATED by scripts/sync.mjs from site.config.js - edit that file, then run \`npm run sync\`.\n# Hand edits here are drift and fail \`npm run sync:check\`.\n`

const TARGETS = [
  {
    path: 'docs/_config.yml',
    render: (s) => `${BANNER}
title: ${yamlStr(s.name)}
baseurl: ${yamlStr(s.docs.baseurl)} # the docs deploy path (the hub is the root, so empty)
url: ${yamlStr(s.docs.host)}
description: ${yamlStr(s.description)}

# Identity the layout renders (docs/_layouts/default.html reads these).
repo: ${yamlStr(s.repo)}
brand_accent: ${yamlStr(s.wordmark.accent.trim())}
brand_rest: ${yamlStr(s.wordmark.rest.trim())}
maker_label: ${yamlStr(s.maker.label)}
maker_url: ${yamlStr(s.maker.url)}
org_name: ${yamlStr(s.org.name)}
org_url: ${yamlStr(s.org.url)}
site_url: ${yamlStr(s.url)}
docs_url: ${yamlStr(s.docs.url)}
theme_key: ${yamlStr(s.theme.themeKey)}
scheme_key: ${yamlStr(s.theme.schemeKey)}

markdown: kramdown
highlighter: rouge
permalink: pretty

# pretty = /path/ (with trailing slug); individual frontmatter overrides.
exclude: ['README.md', 'Gemfile', 'Gemfile.lock', 'tmp', 'pagefind*', 'node_modules', 'freestruct.config.yml', 'vendor']

kramdown:
  syntax_highlighter: rouge
  syntax_highlighter_opts:
    default_lang: plaintext
    css_class: 'highlight'
  toc_levels: [1, 2, 3, 4, 5, 6]
  auto_ids: true
  auto_id_prefix: ''

plugins:
  - jekyll-redirect-from

# The generated pages (index, projs, search) set their own layout in
# frontmatter; everything else falls back to the docs frame.
defaults:
  - scope:
      path: ""
    values:
      layout: default
`,
  },
  {
    path: 'docs/freestruct.config.yml',
    render: (s) => `${BANNER}
site:
  name: ${yamlStr(s.name)}
  # ORIGIN ONLY - no path. Page paths carry the basePath (below); putting the
  # path here too makes the engine join host+path+slug and the strict link
  # check resolve the prefix as a directory (freestruct#32).
  url: ${yamlStr(s.docs.host)}
  description: ${yamlStr(s.description)}

# The deploy path the output tree is served under (Jekyll's baseurl). The hub
# is the root, so this is empty.
basePath: ${yamlStr(s.docs.baseurl)}

# The baked output tree (discovered by freestruct from docs/).
outputDir: _site

# Fail the build on broken internal links (the truth pass).
linkCheck: true

# Auto BreadcrumbList per page (the home page ships none).
breadcrumb: true

# Author identity - ships as a schema.org Person under "founder" on the
# injected Organization JSON-LD block.
author:
  name: ${yamlStr(s.org.name)}
  url: ${yamlStr(s.org.url)}

# Maintainer identity - custom JSON-LD appended after the built-in pair.
jsonLd:
  - "@type": Person
    name: ${yamlStr(s.author)}
    url: ${yamlStr(s.repo)}
    jobTitle: ${yamlStr(`${s.name} maintainer`)}

twitter:
  card: summary_large_image
`,
  },
  {
    // The GitHub Pages custom domain. Derived, not hand-kept: the host is
    // identity, and two hand-maintained copies (here and in the Pages
    // settings) is exactly the drift this repo exists to end. No trailing
    // newline - Pages compares the file body.
    path: 'CNAME',
    render: (s) => new URL(s.docs.host).host,
  },
  {
    // The same domain inside the Jekyll tree, so it rides into docs/_site and
    // the Pages artifact carries it (the Actions deploy keeps the custom
    // domain even if the repo setting is ever cleared).
    path: 'docs/CNAME',
    render: (s) => new URL(s.docs.host).host,
  },
  {
    // The external sidebar groups (the family links). Generated from the
    // `family` block so no brand or domain literal lives in a hand-kept data
    // file (the brand census gate holds that line). The layout concatenates
    // this with docs/_data/nav.yml.
    path: 'docs/_data/family.yml',
    render: (s) => {
      const head = `# GENERATED by scripts/sync.mjs from site.config.js - edit that file, then run \`npm run sync\`.\n# Hand edits here are drift and fail \`npm run sync:check\`.\n`
      const groups = (s.family || []).map((g) => {
        const items = g.items.map((it) => `  - title: ${yamlStr(it.title)}\n    url: ${yamlStr(it.url)}`).join('\n')
        return `- title: ${yamlStr(g.title)}\n  items:\n${items}`
      }).join('\n\n')
      return `${head}\n${groups}\n`
    },
  },
  {
    // The portfolio crawler policy. Generated so the sitemap pointer rides the
    // portfolio URL from one source.
    path: 'web/public/robots.txt',
    render: (s) => `# GENERATED by scripts/sync.mjs from site.config.js - edit that file, then run \`npm run sync\`.\n# Hand edits here are drift and fail \`npm run sync:check\`.\n
# crawler policy - all the way open, it's a personal portfolio
User-agent: *
Allow: /

Sitemap: ${s.portfolio.url}/sitemap.xml
`,
  },
  {
    // The PWA manifest. Generated so the portfolio's name and description stay
    // one source.
    path: 'web/public/site.webmanifest',
    render: (s) =>
      JSON.stringify(
        {
          name: s.portfolio.name,
          short_name: s.portfolio.name,
          description: s.portfolio.description,
          start_url: '/',
          display: 'standalone',
          background_color: '#0a1113',
          theme_color: '#0a1113',
          lang: 'en',
          icons: [
            { src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
            { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
            { src: '/icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' },
          ],
        },
        null,
        2
      ) + '\n',
  },
]

const check = process.argv.includes('--check')
let drifted = 0

for (const t of TARGETS) {
  const abs = join(ROOT, t.path)
  const next = t.render(site)
  const prev = existsSync(abs) ? readFileSync(abs, 'utf8') : null
  if (prev === next) {
    console.log(`sync: ${t.path} up to date`)
    continue
  }
  if (check) {
    console.error(`sync: ${t.path} has DRIFTED from site.config.js - run \`npm run sync\``)
    drifted++
  } else {
    writeFileSync(abs, next)
    console.log(`sync: wrote ${t.path}`)
  }
}

if (check && drifted) {
  console.error(`sync:check: FAIL (${drifted} drifted file(s))`)
  process.exit(1)
}
console.log(check ? 'sync:check: PASS (all derived surfaces current)' : 'sync: PASS (derived surfaces written)')
